// Single funnel for every Daily_Publisher failure mode.
// Classifies LinkedIn auth errors so the alert can name credential expiry (Req 17.4).
const row = $('Get Queued Row').first().json;
const pageId = row.id;
const step = $prevNode.name;
const raw = $input.first().json;
const err = raw.error || raw;

const status = err.httpCode || err.statusCode || err.status;
const message = String(err.message || err.description || '');

if (step === 'Post To LinkedIn') {
  const isAuth = ['401', '403'].includes(String(status))
    || /revoked|expired|invalid[_ ]token|unauthorized/i.test(message);
  const tail = isAuth
    ? '\nThe LinkedIn OAuth2 credential has likely expired. It must be reconnected every 60 days.'
    : '';
  return [{ json: { text: ':x: LinkedIn publish failed\nPage: ' + pageId
    + '\nStatus: ' + String(status || 'unknown')
    + '\nMessage: ' + message
    + '\nRow stays Queued and will retry on the next run.' + tail } }];
}

if (step === 'Mark Published') {
  return [{ json: { text: ':warning: Published but unmarked\nPage: ' + pageId
    + '\nThe post reached LinkedIn but the Notion status update failed.'
    + '\nSet it to Published manually to prevent a duplicate post.' } }];
}

if (step === 'Download Image') {
  return [{ json: { text: ':x: Image download failed\nPage: ' + pageId
    + '\nReason: ' + (message || 'unknown')
    + '\nRow stays Queued and will retry on the next run.' } }];
}

// Empty Image Link path: the row was set to Needs Edit rather than left Queued.
return [{ json: { text: ':warning: Missing image link\nPage: ' + pageId
  + '\nRow set to Needs Edit. Add an Image Link before re-queueing.' } }];

const TRACKING_PREFIXES = ['utm_', 'mc_'];
const TRACKING_KEYS = new Set(['fbclid', 'gclid', 'msclkid', 'igshid', 'ref', 'ref_src', 'source', 'mkt_tok', 'yclid', '_hsenc', '_hsmi', 'vero_id']);

const out = [];
for (const item of $input.all()) {
  const link = item.json.link || item.json.url || '';
  if (!link) continue;
  let sourceUrl;
  try {
    const u = new URL(String(link).trim());
    u.hash = '';
    u.protocol = u.protocol.toLowerCase();
    u.hostname = u.hostname.toLowerCase();
    for (const k of [...u.searchParams.keys()]) {
      const lower = k.toLowerCase();
      if (TRACKING_KEYS.has(lower) || TRACKING_PREFIXES.some(function(p) { return lower.startsWith(p); })) {
        u.searchParams.delete(k);
      }
    }
    u.searchParams.sort();
    let r = u.toString();
    if (r.endsWith('?')) r = r.slice(0, -1);
    const qi = r.indexOf('?');
    let base = qi >= 0 ? r.slice(0, qi) : r;
    const q = qi >= 0 ? r.slice(qi + 1) : '';
    if (base.endsWith('/') && new URL(base).pathname !== '/') base = base.slice(0, -1);
    sourceUrl = q ? base + '?' + q : base;
  } catch (e) {
    continue;
  }
  const host = new URL(sourceUrl).hostname;
  const pub = host.startsWith('www.') ? host.slice(4) : host;
  out.push({ json: { sourceUrl: sourceUrl, title: String(item.json.title || sourceUrl).slice(0, 200), publication: pub } });
}
return out;

// Single funnel for every Content_Factory failure and quality-gate rejection.
// Emits a uniform payload so one Notion node and one Slack node serve all paths.
let pageId = null;
try { pageId = $('Create Row Processing').first().json.id || null; } catch (e) { pageId = null; }

let sourceUrl = '';
try { sourceUrl = $('Loop Over Items').first().json.sourceUrl || ''; } catch (e) { sourceUrl = ''; }

const raw = $input.first().json;
const step = $prevNode.name;

// Style-rule exhaustion arrives with violations rather than an error object,
// and is the one path that also writes the rejected copy back for human editing.
if (Array.isArray(raw.violations) && raw.violations.length > 0) {
  const rules = raw.violations.map(v => v.rule).join(', ');
  return [{ json: {
    pageId,
    sourceUrl,
    step: 'Style Validator',
    reason: 'Style violations persist after one regeneration: ' + rules,
    copy: raw.copy || '',
    icon: ':warning:'
  } }];
}

// Markdown gate rejection: scrape succeeded but the body was too thin to use.
if (step === 'If Markdown Long Enough') {
  const d = raw.data || raw;
  const len = String(d.markdown || '').length;
  return [{ json: {
    pageId,
    sourceUrl,
    step: 'Firecrawl Scrape',
    reason: 'Article markdown too short to use (' + len + ' chars)',
    copy: '',
    icon: ':warning:'
  } }];
}

// Everything else is a genuine node failure off an error output.
const err = raw.error || raw;
return [{ json: {
  pageId,
  sourceUrl,
  step,
  reason: String((err && err.message) || err || 'unknown'),
  copy: '',
  icon: ':x:'
} }];

